PRAGMA foreign_keys=ON;
CREATE TABLE huespedes (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, dni TEXT NOT NULL UNIQUE, email TEXT NOT NULL UNIQUE, pais TEXT NOT NULL);
CREATE TABLE habitaciones (id INTEGER PRIMARY KEY AUTOINCREMENT, numero TEXT NOT NULL UNIQUE, tipo TEXT NOT NULL CHECK(tipo IN ('INDIVIDUAL','DOBLE','SUITE')), planta INTEGER NOT NULL CHECK(planta >= 0), precio_noche NUMERIC NOT NULL CHECK(precio_noche > 0));
CREATE TABLE reservas (id INTEGER PRIMARY KEY AUTOINCREMENT, id_huesped INTEGER NOT NULL REFERENCES huespedes(id) ON DELETE RESTRICT, id_habitacion INTEGER NOT NULL REFERENCES habitaciones(id) ON DELETE RESTRICT, fecha_entrada TEXT NOT NULL, noches INTEGER NOT NULL CHECK(noches > 0), estado TEXT NOT NULL CHECK(estado IN ('CONFIRMADA','CANCELADA','FINALIZADA')));
CREATE TABLE consumos (id INTEGER PRIMARY KEY AUTOINCREMENT, id_reserva INTEGER NOT NULL REFERENCES reservas(id) ON DELETE RESTRICT, concepto TEXT NOT NULL, cantidad INTEGER NOT NULL CHECK(cantidad > 0), precio_unitario NUMERIC NOT NULL CHECK(precio_unitario >= 0), fecha TEXT NOT NULL);
